action.code:
size_t hash1, hash2;
ckh->hash(key, &hash1, &hash2);
size_t bucket1 = hash1 & ((1 << ckh->lg_curbuckets) - 1);
size_t bucket2 = hash2 & ((1 << ckh->lg_curbuckets) - 1);

// Try to insert into first bucket
if (ckh_try_bucket_insert(ckh, bucket1, key, data)) {
    return false;
}

// Try to insert into second bucket
if (ckh_try_bucket_insert(ckh, bucket2, key, data)) {
    return false;
}

// Both buckets full, need to evict
size_t bucket = (ckh->prng_state & 1) ? bucket1 : bucket2;
if (ckh_evict_reloc_insert(ckh, bucket, key, data)) {
    return false;
}

// Eviction failed, table needs to grow
return true;

